<script setup lang="ts">
import { computed,ref } from 'vue'
import AppPage from '../../components/AppPage.vue'
import Icon from '../../components/Icon.vue'
import { useHealthStore } from '../../stores/health'
import { dateKey,shiftDate,weekStart,weekDays,shortDate } from '../../domain/dates'
import { weeklySummary } from '../../domain/nutrition'
import { display,navigate } from '../../utils/ui'
const store=useHealthStore(),selected=ref(dateKey()),summary=computed(()=>weeklySummary(store.data,selected.value))
const days=computed(()=>weekDays(selected.value)),recordDays=computed(()=>new Set(store.data.meals.filter(x=>days.value.includes(x.date)).map(x=>x.date)))
const canNext=computed(()=>weekStart(shiftDate(selected.value,7))<=weekStart(dateKey()))
const observation=computed(()=>{const s=summary.value;if(!s.days&&!s.sessions)return '这一周还没有饮食和训练记录。从方便的一餐或一次散步开始，逐渐找到自己的记录节奏。';return `这一周，你在 ${s.days} 天留下了饮食记录，也记录了 ${s.sessions} 次训练、累计 ${s.minutes} 分钟。记录本身，就是了解自己的第一步。`})
</script>
<template><AppPage title="每周回顾"><text class="eyebrow">LOOK BACK, MOVE FORWARD</text><text class="page-title">把这一周，还给自己</text><text class="page-description">回看真实记录，发现一点点积累。</text><view class="week-switcher"><button role="button" class="icon-button small" aria-label="上一周" @click="selected=shiftDate(selected,-7)"><Icon name="back" :size="15"/></button><view><text class="week-range">{{ shortDate(summary.start) }} — {{ shortDate(summary.end) }}</text><text class="week-year">{{ summary.start.slice(0,4) }} · {{ weekStart(selected)===weekStart(dateKey())?'本周':'过往一周' }}</text></view><button role="button" class="icon-button small" aria-label="下一周" :disabled="!canNext" @click="selected=shiftDate(selected,7)"><Icon name="arrow" :size="15"/></button></view><view class="review-hero"><Icon name="leaf" tone="white" :size="29"/><text class="review-hero-title">每一小步，都有回响。</text><text class="review-hero-copy">{{ observation }}</text></view><view class="review-grid section"><view class="card review-stat"><Icon name="bowl" :size="20"/><text class="review-number number">{{ summary.days }}<text> / 7 天</text></text><text class="review-label">有饮食记录</text></view><view class="card review-stat"><Icon name="dumbbell" :size="20"/><text class="review-number number">{{ summary.sessions }}<text> 次</text></text><text class="review-label">训练记录</text></view><view class="card review-stat"><Icon name="clock" :size="20"/><text class="review-number number">{{ summary.minutes }}<text> 分钟</text></text><text class="review-label">累计训练</text></view><view class="card review-stat"><Icon name="scale" :size="20"/><text class="review-number number">{{ summary.weightChange===undefined?'—':(summary.weightChange>0?'+':'')+summary.weightChange.toFixed(1) }}<text> kg</text></text><text class="review-label">周内首末体重变化</text></view></view><view class="section"><view class="section-heading"><text class="section-title">这一周的饮食节奏</text><text class="section-caption">FOOD JOURNAL</text></view><view class="card"><view class="review-days"><view v-for="(day,i) in days" :key="day" class="review-day"><text>{{ ['一','二','三','四','五','六','日'][i] }}</text><view :class="{logged:recordDays.has(day),future:day>dateKey()}"><Icon v-if="recordDays.has(day)" name="check" tone="white" :size="15"/><text v-else>·</text></view></view></view><view class="divider"/><view class="review-detail"><text>有记录日的平均摄入</text><text>{{ display(summary.averageKcal) }} <text class="muted">kcal</text></text></view><view class="review-detail"><text>热量在目标 ±10% 的记录日</text><text>{{ summary.energyDays===undefined?'未设目标':summary.energyDays+' / '+summary.days+' 天' }}</text></view><view class="review-detail"><text>蛋白质达到目标的记录日</text><text>{{ summary.proteinDays===undefined?'未设目标':summary.proteinDays+' / '+summary.days+' 天' }}</text></view><text class="helper mt-16">仅统计已记录食物；有记录不代表当天饮食已完整记录，缺失日不计为0摄入。目标完成情况按当前设置计算。</text></view></view><view class="notice mt-24"><Icon name="info" :size="20"/><text>周内体重变化需要至少两天的体重记录。单周变化不等于脂肪变化，结合更长时间趋势观察。</text></view><view class="section"><text class="section-title">下周，继续自己的节奏</text><text class="page-description">选择方便的记录时机，让工具适应你的生活。</text><view class="action-row mt-16"><button role="button" class="btn-secondary" @click="navigate('body')">查看身体趋势</button><button role="button" class="btn-primary" @click="navigate('goals')">调整我的目标</button></view></view><text class="footer-note">本页基于本地记录汇总，不做医学判断。</text></AppPage></template>
<style scoped>.week-switcher{display:flex;align-items:center;justify-content:space-between;text-align:center;margin:26px 0 22px}.week-range{font-size:17px;letter-spacing:.5px;font-weight:600;display:block}.week-year{font-size:10px;color:var(--muted);display:block;margin-top:6px}.review-hero{background:var(--forest);color:white;border-radius:20px;padding:24px}.review-hero-title{display:block;font-size:21px;font-weight:550;letter-spacing:.5px;margin-top:15px}.review-hero-copy{display:block;color:#c0cfb6;font-size:12px;line-height:2.1;margin-top:13px}.review-grid{display:grid;grid-template-columns:1fr 1fr;gap:12px}.review-stat{padding:18px}.review-number{font-size:29px;font-weight:600;display:block;margin-top:15px}.review-number text{font-size:11px;letter-spacing:0;font-weight:400;color:var(--muted)}.review-label{font-size:10px;color:var(--muted);display:block;margin-top:8px}.review-days{display:flex;justify-content:space-between;gap:8px}.review-day{flex:1;display:flex;flex-direction:column;align-items:center;gap:11px;font-size:10px;color:var(--muted)}.review-day>view{width:29px;height:31px;border-radius:10px;background:#edf0e6;display:flex;align-items:center;justify-content:center}.review-day>view.logged{background:#5f8250}.review-day>view.future{opacity:.35}.review-detail{display:flex;justify-content:space-between;gap:8px;font-size:11px;margin:16px 0}.review-detail>text:first-child{color:#8b9683}.review-detail>text:last-child{font-weight:550}.action-row .btn-primary,.action-row .btn-secondary{font-size:12px}</style>
